import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    inf = n + 1

    # best[x][l] is the minimum R among constraints with X=x and L>=l.
    best = [[inf] * (n + 2) for _ in range(n + 1)]
    p = 2
    for _ in range(m):
        l, r, x = data[p], data[p + 1], data[p + 2]
        p += 3
        if r < best[x][l]:
            best[x][l] = r
    for x in range(1, n + 1):
        row = best[x]
        for l in range(n - 1, 0, -1):
            if row[l + 1] < row[l]:
                row[l] = row[l + 1]

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for root in range(l, r + 1):
                if best[root][l] <= r:
                    continue
                total += (dp[l][root - 1] * dp[root + 1][r] % MOD) * comb[length - 1][root - l]
            dp[l][r] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    main()

