class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ends = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ends[b].append((a, i))

        top = 0
        second = 0
        top_count = 0
        top_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in ends[right]:
                if left > top:
                    second = top
                    top = left
                    top_count = 1
                    top_id = idx
                elif left == top:
                    top_count += 1
                elif left > second:
                    second = left

            total += right - top
            if top_count == 1:
                gains[top_id] += top - second

        return total + max(gains)

