    for _ in range(q):
        t=next(it); z=next(it)-1
        if t==1: queries.append((1,z)); closures.append(z); closed[z]=True
        else: queries.append((2,z,next(it)-1))
    INF=10**30; d=[[INF]*n for _ in range(n)]
    for i in range(n): d[i][i]=0
    for k,(u,v,w) in enumerate(edges):
