                if d[i][k]+d[k][j]<d[i][j]: d[i][j]=d[i][k]+d[k][j]
    K=len(closures); buckets=[[] for _ in range(K+1)]; ans=[]; state=0
    for z in queries:
        if z[0]==1: state+=1
        else: buckets[state].append((len(ans),z[1],z[2])); ans.append(0)
