import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    vals = data[2:]
    machines = [vals[4*i:4*i+4] for i in range(n)]

    def feasible(w):
        total = 0
        for a, p, b, q in machines:
            kmax = (w + a - 1) // a
            best = 10**30
            # Between consecutive multiples of b, the cost is linear in k.
            # Thus it suffices to check the endpoints, including the point
            # just before the all-S boundary.
            candidates = set(range(min(b, kmax) + 1))
            candidates.update(range(max(0, kmax - b), kmax + 1))
            for k in candidates:
                remaining = w - k * a
                cost = k * p
                if remaining > 0:
                    cost += (remaining + b - 1) // b * q
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, 1_000_000_001
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == "__main__":
    solve()

