class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients for choosing the one-bits in a suffix.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # Number of operations needed to reduce each possible popcount to 1.
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            y = x
            d = 0
            while y > 1:
                y = y.bit_count()
                d += 1
            depth[x] = d

        answer = 0
        ones_before = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for suffix_ones in range(remaining + 1):
                    total_ones = ones_before + suffix_ones
                    # The differing bit is changed from 1 to 0.  A positive
                    # number requires at least one set bit.
                    if total_ones >= 1 and depth[total_ones] <= k - 1:
                        answer = (answer + comb[remaining][suffix_ones]) % MOD
                ones_before += 1
        return answer

