class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        C = [[0]*(L+1) for _ in range(L+1)]
        C[0][0] = 1
        for i in range(1, L+1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        depth = [0]*(L+1)
        for x in range(2, L+1):
            y=x; cnt=0
            while y>1:
                y = y.bit_count(); cnt += 1
            depth[x]=cnt
        good = [depth[r] <= k-1 for r in range(L+1)]
        ans=0
        pref=0
        for i,ch in enumerate(s):
            if ch=='1':
                rem=L-i-1
                for t in range(rem+1):
                    r=pref+t
                    if r>=1 and good[r]:
                        ans=(ans+C[rem][t])%MOD
                pref += 1
        return ans

