import sys, heapq

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    rows = [x.decode() for x in data[1:]]
    edges = []
    labels = set()
    for i, row in enumerate(rows):
        for j, ch in enumerate(row):
            if ch != '-':
                edges.append((i, j, ch))
                labels.add(ch)

    # If there is only one label, every path is palindromic, so this is APSP.
    if len(labels) <= 1:
        inf = 10**9
        d = [[inf] * n for _ in range(n)]
        for i in range(n):
            d[i][i] = 0
        for i, j, _ in edges:
            d[i][j] = 1
        for k in range(n):
            dk = d[k]
            for i in range(n):
                nd = d[i][k]
                if nd == inf:
                    continue
                di = d[i]
                for j in range(n):
                    z = nd + dk[j]
                    if z < di[j]:
                        di[j] = z
        print('\n'.join(' '.join(str(-1 if x == inf else x) for x in r) for r in d))
        return

    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    for i, j, ch in edges:
        c = ord(ch) - 97
        out[i][c].append(j)
        inc[j][c].append(i)

    inf = 10**9
    d = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        d[i][i] = 0
        heapq.heappush(heap, (0, i * n + i))
    for i, j, _ in edges:
        if d[i][j] > 1:
            d[i][j] = 1
            heapq.heappush(heap, (1, i * n + j))

    while heap:
        dist, state = heapq.heappop(heap)
        u, v = divmod(state, n)
        if dist != d[u][v]:
            continue
        nd = dist + 2
        for c in range(26):
            for x in inc[u][c]:
                dx = d[x]
                for y in out[v][c]:
                    if nd < dx[y]:
                        dx[y] = nd
                        heapq.heappush(heap, (nd, x * n + y))

    print('\n'.join(' '.join(str(-1 if x == inf else x) for x in r) for r in d))

if __name__ == '__main__':
    main()

