import sys

sys.setrecursionlimit(10000)

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    limit = 1 << 100
    low = 1
    high = limit - a[-1] - 1

    def feasible(r, mod):
        if r < low:
            r += ((low - r + mod - 1) // mod) * mod
        return r <= high

    def dfs(d, residue, active, score):
        if not active:
            return score if feasible(residue, 1 << d) else -10**9
        if d == 100:
            return -10**9
        step = 1 << d
        mod = step << 1
        best = -10**9
        for bit in (0, 1):
            r = residue + bit * step
            next_active = []
            cur = score
            for x in active:
                y = r + x
                if y % mod == 0:
                    next_active.append(x)
                else:
                    t = (y & -y).bit_length() - 1
                    if ((y >> (t + 1)) & 1) == 0:
                        cur += 1
            best = max(best, dfs(d + 1, r, next_active, cur))
        return best

    print(dfs(0, 0, a, 0))

if __name__ == '__main__':
    main()

