import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix to RREF over GF(2).
    r = 0
    pivots = []
    for c in range(n):
        q = None
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                q = i
                break
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    null_basis = []
    for f in free:
        x = 1 << f
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                x |= 1 << c
        null_basis.append(x)

    # Every coordinate must occur in some nullspace vector; otherwise it
    # would necessarily receive zero in every possible solution.
    for i in range(n):
        if not any((x >> i) & 1 for x in null_basis):
            print("No")
            return

    ans = [0] * n
    for bit, x in enumerate(null_basis):
        for i in range(n):
            if (x >> i) & 1:
                ans[i] |= 1 << bit
    print("Yes")
    print(*ans)

if __name__ == "__main__":
    main()

