from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        available = list(range(1, n + 1))
        result = []
        last_parity = None

        def completions(odd_left, even_left, last):
            length = odd_left + even_left
            if length == 0:
                return 1
            next_parity = 1 - last
            next_slots = (length + 1) // 2
            other_slots = length // 2
            if next_parity == 1:
                if odd_left != next_slots or even_left != other_slots:
                    return 0
            else:
                if even_left != next_slots or odd_left != other_slots:
                    return 0
            return fact[odd_left] * fact[even_left]

        for _ in range(n):
            for value in available:
                parity = value & 1
                if last_parity is not None and parity == last_parity:
                    continue
                odd_left = sum(v & 1 for v in available) - parity
                even_left = len(available) - 1 - odd_left
                count = completions(odd_left, even_left, parity)
                if k > count:
                    k -= count
                else:
                    result.append(value)
                    available.remove(value)
                    last_parity = parity
                    break
            else:
                return []
        return result

