class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # The contribution modulo k of each digit in the first half.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k
        weights = []
        for i in range(half):
            j = n - 1 - i
            if i == j:
                weights.append(powers[i])
            else:
                weights.append((powers[i] + powers[j]) % k)

        # shift[d][mask] is the residue mask after adding d modulo k.
        mask_count = 1 << k
        shift = [[0] * mask_count for _ in range(k)]
        for amount in range(k):
            for mask in range(mask_count):
                result = 0
                for residue in range(k):
                    if mask & (1 << residue):
                        result |= 1 << ((residue + amount) % k)
                shift[amount][mask] = result

        # suffix[i] contains all residues attainable by positions i onward.
        suffix = [0] * (half + 1)
        suffix[half] = 1  # residue zero
        for i in range(half - 1, -1, -1):
            possible = 0
            for digit in range(10):
                possible |= shift[(digit * weights[i]) % k][suffix[i + 1]]
            suffix[i] = possible

        first_half = []
        remainder = 0
        for i, weight in enumerate(weights):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-(remainder + digit * weight)) % k
                if suffix[i + 1] & (1 << needed):
                    first_half.append(str(digit))
                    remainder = (remainder + digit * weight) % k
                    break

        mirror = first_half[:-1] if n % 2 else first_half
        return ''.join(first_half + mirror[::-1])

