        for i in range(n): cb[i]=nums[i]*(nxt[i]-i)-(pre[nxt[i]]-pre[i])
        costs=[cb]
        for j in range(1,LOG):
            pa=anc[-1]; ca=costs[-1]; na=[n]*n; nc=[0]*n
            for i in range(n):
                m=pa[i]; na[i]=pa[m] if m<n else n; nc[i]=ca[i]+(ca[m] if m<n else 0)
            anc.append(na); costs.append(nc)
        def get(l,r):
            p=l; c=0
            for j in range(LOG-1,-1,-1):
                q=anc[j][p]
                if q<=r:
                    c+=costs[j][p]; p=q
            c += nums[p]*(r+1-p)-(pre[r+1]-pre[p])
            return c
        ans=0
        for r in range(n):
            lo=0; hi=r
            while lo<hi:
                m=(lo+hi)//2
                if get(m,r)<=k: hi=m
                else: lo=m+1
            ans += r-lo+1
        return ans

