class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        without_parent = [0] * n
        with_parent = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += without_parent[v]
                    gains.append(w + with_parent[v] - without_parent[v])
            gains.sort(reverse=True)

            take = 0
            for gain in gains[:k]:
                if gain <= 0:
                    break
                take += gain
            without_parent[u] = base + take

            take = 0
            for gain in gains[:k - 1]:
                if gain <= 0:
                    break
                take += gain
            with_parent[u] = base + take

        return without_parent[0]

