import sys
from functools import lru_cache


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    initial = tuple([0] * n + [1] * m + [2] * l)

    @lru_cache(maxsize=None)
    def winning(state, player):
        for i in range(total):
            if state[i] != player:
                continue
            after_play = list(state)
            after_play[i] = 2

            # The player may choose not to take a card.
            if not winning(tuple(after_play), 1 - player):
                return True

            # Or take any strictly smaller card currently on the table.
            for j in range(total):
                if state[j] == 2 and values[j] < values[i]:
                    after_take = after_play.copy()
                    after_take[j] = player
                    if not winning(tuple(after_take), 1 - player):
                        return True
        return False

    print("Takahashi" if winning(initial, 0) else "Aoki")


if __name__ == "__main__":
    main()

