class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def starts(t):
            m = len(t)
            if m == 0:
                return None
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            ans = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    ans.append(i - m + 1)
                    j = pi[j - 1]
            return ans

        def next_occurrence(t):
            found = starts(t)
            nxt = [n + 1] * (n + 2)
            if not t:
                for i in range(n, -1, -1):
                    nxt[i] = i
            else:
                for pos in found:
                    nxt[pos] = pos
                for i in range(n - 1, -1, -1):
                    if nxt[i] == n + 1:
                        nxt[i] = nxt[i + 1]
            return nxt

        nb = next_occurrence(b)
        nc = next_occurrence(c)
        possible_a = starts(a)
        if not a:
            possible_a = range(n + 1)

        la, lb, lc = len(a), len(b), len(c)
        best = n + 1
        for x in possible_a:
            after_a = x + la
            if after_a > n:
                continue
            y = nb[after_a]
            if y > n:
                continue
            after_b = y + lb
            if after_b > n:
                continue
            z = nc[after_b]
            if z <= n:
                best = min(best, z + lc - x)
        return -1 if best == n + 1 else best

