import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    k = int(data[0])
    a, b = data[1], data[2]

    p = 0
    lim = min(len(a), len(b))
    while p < lim and a[p] == b[p]:
        p += 1
    a, b = a[p:], b[p:]

    q = 0
    lim = min(len(a), len(b))
    while q < lim and a[-1-q] == b[-1-q]:
        q += 1
    if q:
        a, b = a[:-q], b[:-q]

    if abs(len(a) - len(b)) > k:
        print("No")
        return
    if len(a) > len(b):
        a, b = b, a

    n, m = len(a), len(b)
    inf = k + 1
    prev = [inf] * (m + 1)
    cur = [inf] * (m + 1)
    for j in range(min(m, k) + 1):
        prev[j] = j

    for i in range(1, n + 1):
        lo = max(0, i - k)
        hi = min(m, i + k)
        if lo == 0:
            cur[0] = i
            start = 1
        else:
            start = lo
        prev_hi = min(m, i - 1 + k)
        row_min = cur[0] if lo == 0 else inf
        for j in range(start, hi + 1):
            deletion = prev[j] if j <= prev_hi else inf
            insertion = cur[j - 1] if j > lo else inf
            diagonal = prev[j - 1]
            v = diagonal if a[i - 1] == b[j - 1] else diagonal + 1
            if deletion + 1 < v:
                v = deletion + 1
            if insertion + 1 < v:
                v = insertion + 1
            if v > inf:
                v = inf
            cur[j] = v
            if v < row_min:
                row_min = v
        if row_min > k:
            print("No")
            return
        prev, cur = cur, prev

    print("Yes" if prev[m] <= k else "No")

