from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Build the postorder string iteratively.  Each subtree is an interval
        # in this string.
        order = []
        end = [0] * n
        size = [0] * n
        stack = [(0, 0)]
        while stack:
            x, state = stack.pop()
            if state == 0:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))
            else:
                total = 1
                for y in children[x]:
                    total += size[y]
                size[x] = total
                end[x] = len(order)
                order.append(s[x])

        # Manacher radii for odd and even palindromes in the postorder string.
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and order[i - k] == order[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and order[i - k - 1] == order[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            r = end[x]
            l = r - size[x] + 1
            length = size[x]
            if length & 1:
                answer[x] = d1[(l + r) // 2] >= length // 2 + 1
            else:
                answer[x] = d2[(l + r + 1) // 2] >= length // 2
        return answer

