class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        inf = 10**30
        min_prefix = [inf] * k
        min_prefix[0] = 0
        prefix = 0
        answer = -inf

        for index, value in enumerate(nums, 1):
            prefix += value
            remainder = index % k
            if min_prefix[remainder] != inf:
                answer = max(answer, prefix - min_prefix[remainder])
            if prefix < min_prefix[remainder]:
                min_prefix[remainder] = prefix

