    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0

        # dp[i] is a bitset: bit s is set iff sum s can be formed at index i.
        dp = [1] * n
        masks = [(1 << (x + 1)) - 1 for x in nums]

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] = (dp[i] | (dp[i] << value)) & masks[i]
            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k
        return -1

