import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits

        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = [False] * (((limit - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        distance = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if distance.get(value) != cost:
                continue
            if value == m:
                return cost

            text = str(value).zfill(digits)
            for pos, char in enumerate(text):
                digit = ord(char) - ord('0')
                for new_digit in (digit - 1, digit + 1):
                    if 0 <= new_digit <= 9:
                        next_value = int(
                            text[:pos] + str(new_digit) + text[pos + 1:]
                        )
                        if not prime[next_value]:
                            next_cost = cost + next_value
                            if next_cost < distance.get(next_value, float('inf')):
                                distance[next_value] = next_cost
                                heapq.heappush(heap, (next_cost, next_value))

        return -1

