from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        def zfunc(offset: int, limit: int):
            m = n - offset
            z = [0] * (limit + 1)
            left = right = 0
            for k in range(1, limit + 1):
                if k < right:
                    z[k] = min(z[k - left], right - k)
                while (k + z[k] < m and
                       nums[offset + z[k]] == nums[offset + k + z[k]]):
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]
            return z

        # prefix[i] is the LCP length of nums and nums[i:].
        prefix = zfunc(0, n - 1)
        answer = 0

        for i in range(1, n - 1):
            first = prefix[i] >= i
            if first:
                # j >= 2*i is required, and j <= n-1.
                answer += max(0, n - max(i + 1, 2 * i))

            # Here d = j-i.  The second condition requires d <= n-j,
            # hence d <= (n-i)//2.  The Z values are for suffix nums[i:].
            limit = (n - i) // 2
            row = zfunc(i, limit)
            for d in range(1, limit + 1):
                if row[d] >= d:
                    answer += 1
                    # A split may satisfy both conditions; count it once.
                    if first and d >= i:
                        answer -= 1

        return answer

