class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        inf = 10**18
        best = [inf] * n
        best[0] = 0
        heap = [(0, 0)]

        while heap:
            value, node = heapq.heappop(heap)
            if value != best[node]:
                continue
            for prev, weight in reverse[node]:
                candidate = max(value, weight)
                if candidate < best[prev]:
                    best[prev] = candidate
                    heapq.heappush(heap, (candidate, prev))

        result = max(best)
        return -1 if result == inf else result

