        INF = 10**30
        dp = [[INF] * 3 for _ in range(3)]

        # Process houses symmetrically from the two ends.
        for left_color in range(3):
            for right_color in range(3):
                if left_color != right_color:
                    dp[left_color][right_color] = (
                        cost[0][left_color] + cost[n - 1][right_color]
                    )

        for i in range(1, n // 2):
            next_dp = [[INF] * 3 for _ in range(3)]
            j = n - 1 - i
            for left_color in range(3):
                for right_color in range(3):
                    if left_color == right_color:
                        continue
                    pair_cost = cost[i][left_color] + cost[j][right_color]
                    best_previous = INF
                    for prev_left in range(3):
                        for prev_right in range(3):
                            if prev_left != left_color and prev_right != right_color:
                                best_previous = min(
                                    best_previous, dp[prev_left][prev_right]
                                )
                    next_dp[left_color][right_color] = best_previous + pair_cost
            dp = next_dp

