class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            x = ord(ch) - ord('a')
            mirror = 25 - x
            if stacks[mirror]:
                score += i - stacks[mirror].pop()
            else:
                stacks[x].append(i)
        return score

